package expo.modules.plugin.android

import com.android.build.gradle.LibraryExtension

internal fun LibraryExtension.applySDKVersions(compileSdk: Int, minSdk: Int, targetSdk: Int) {
  this.compileSdk = compileSdk
  defaultConfig {
    this@defaultConfig.minSdk = minSdk
    // [with-agp9-compat] LibraryDefaultConfig.setTargetSdk(Integer) was removed in AGP 9;
    // a library's targetSdk is ignored by the app manifest merge anyway.
  }
  // [with-agp9-compat] AGP 9 disables the buildConfig feature by default,
  // but expo modules add custom BuildConfig fields.
  buildFeatures { buildConfig = true }
}

internal fun LibraryExtension.applyLinterOptions() {
  // [with-agp9-compat] lintOptions was removed in AGP 9; debug builds do not run lint.
}

internal fun LibraryExtension.applyPublishingVariant() {
  publishing { publishing ->
    publishing.singleVariant("release") {
      withSourcesJar()
    }
  }
}
